# -*- coding: utf-8 -*-

import ccxt.async_support as ccxt  # noqa: F402

def test_check_address():
    exchange = ccxt.Exchange({
        'id': 'sampleexchange',
    })
    address = 'rDsbeomae4FXwgQTJp9Rs64Qg9vDiTCdBv'
    # currencies without a tag requirement pass with or without a tag
    assert exchange.check_address(address) == address
    assert exchange.check_address(address, 'BTC') == address
    # tag-required currencies need a tag
    assert exchange.check_address(address, 'XRP', '123456') == address
    assert exchange.check_address(address, 'ATOM', '123456') == address
    caught = False
    try:
        exchange.check_address(address, 'XRP')
    except Exception as error:
        caught = True
    assert caught, 'XRP without a tag should have thrown'
    caught = False
    try:
        exchange.check_address(address, 'XLM', None)
    except Exception as error:
        caught = True
    assert caught, 'XLM without a tag should have thrown'
    caught = False
    try:
        exchange.check_address(None, 'BTC')
    except Exception as error:
        caught = True
    assert caught, 'an undefined address should have thrown'
